def attack_graph(guide,root):
 """Render the same documented relations as SVG and a visible text equivalent."""
 import json
 graph=json.loads((root/'content/attack-graphs.json').read_text(encoding='utf-8'))[guide]
 nodes=graph['nodes'];edges=graph['edges']
 if len(edges)!=len(nodes)-1:raise ValueError('A case graph must connect every documented step')
 for i,edge in enumerate(edges):
  if edge['from']!=nodes[i]['id'] or edge['to']!=nodes[i+1]['id']:
   raise ValueError('Case graph relations must match the visible text order')
 def svg(narrow):
  variant='narrow' if narrow else 'wide';marker=f'{guide}-arrow-{variant}'
  positions=[(20,20+i*108) for i in range(len(nodes))] if narrow else [(20,20),(270,20),(520,20),(520,172),(270,172),(20,172)][:len(nodes)]
  width=280 if narrow else 760;height=20+(len(nodes)-1)*108+80 if narrow else 272;box_width=240 if narrow else 220
  content=f'<defs><marker id="{marker}" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0 L8 4 L0 8 Z"/></marker></defs>'
  for i,edge in enumerate(edges):
   x,y=positions[i];nx,ny=positions[i+1]
   if ny!=y:
    points=f'{x+box_width/2:g},{y+82:g} {nx+box_width/2:g},{ny-3:g}';lx=x+box_width/2+18;ly=(y+80+ny)/2+5
   elif nx>x:
    points=f'{x+box_width+2:g},{y+40:g} {nx-3:g},{ny+40:g}';lx=(x+box_width+nx)/2;ly=y+30
   else:
    points=f'{x-2:g},{y+40:g} {nx+box_width+3:g},{ny+40:g}';lx=(x+nx+box_width)/2;ly=y+30
   content+=f'<g data-graph-edge="{escape(edge["label"],quote=True)}" data-from="{escape(edge["from"],quote=True)}" data-to="{escape(edge["to"],quote=True)}"><polyline points="{points}" marker-end="url(#{marker})"/><text class="graph-edge-key" x="{lx:g}" y="{ly:g}">{chr(65+i)}</text></g>'
  for i,(node,(x,y)) in enumerate(zip(nodes,positions)):
   lines=node['lines'];start=y+53 if len(lines)==1 else y+44
   labels=''.join(f'<tspan x="{x+box_width/2:g}" y="{start+j*22:g}">{escape(line)}</tspan>' for j,line in enumerate(lines))
   content+=f'<g data-graph-node="{escape(node["id"],quote=True)}"><rect x="{x}" y="{y}" width="{box_width}" height="80" rx="5"/><text class="graph-node-key" x="{x+15}" y="{y+18}">{i+1:02d}</text><text class="graph-node-label">{labels}</text></g>'
  return f'<svg class="case-graph-svg graph-{variant}" viewBox="0 0 {width} {height}" xmlns="http://www.w3.org/2000/svg" aria-hidden="true" focusable="false">{content}</svg>'
 items=''
 for i,node in enumerate(nodes):
  incoming=f'<p class="graph-relation"><b>{chr(64+i)} · {escape(edges[i-1]["label"])}</b>, desde el paso {i:02d} al {i+1:02d}.</p>' if i else ''
  links=''.join(f'<a href="{escape(link["url"],quote=True)}">{escape(link["label"])}</a>' for link in node['evidence'])
  items+=f'<li data-graph-step="{escape(node["id"],quote=True)}"><h3><span class="graph-step-key">{i+1:02d}</span> {escape(" · ".join(node["lines"]))}</h3>{incoming}<p>{escape(node["text"])}</p><div class="graph-source-links">{links}</div></li>'
 result=f'<p class="graph-result"><b>Resultado descrito:</b> {escape(graph["result"])}</p>' if graph.get('result') else ''
 return (f'<section id="mapa" class="case-graph" aria-labelledby="{guide}-graph-title" data-case-graph="{guide}"><h2 id="{guide}-graph-title">Mapa del caso documentado</h2><p class="graph-heading">{escape(graph["title"])}</p><p>{escape(graph["scope"])}</p>'
  +f'<figure class="graph-figure">{svg(False)}{svg(True)}<figcaption>Los números identifican pasos; las letras identifican relaciones dirigidas. La lectura equivalente y sus fuentes están debajo. El color no codifica permisos ni resultados.</figcaption></figure>'
  +f'<ol class="graph-text" aria-label="Pasos y relaciones del mapa">{items}</ol>{result}<p class="graph-limit"><b>Límite del mapa:</b> {escape(graph["limit"])}</p></section>')

def evidence_dossier(guide,root):
 import json
 data=json.loads((root/'content/expedientes.json').read_text(encoding='utf-8'))[guide]
 cards=''
 for i,decision in enumerate(data,1):
  items=''.join(f'<div class="dossier-field"><h3>{escape(label)}</h3><p>{escape(decision[key])}</p></div>' for key,label in [('observation','Observación documentada'),('hypothesis','Hipótesis'),('decision','Decisión retrospectiva'),('alternative','Alternativa de análisis'),('result','Resultado descrito'),('limit','Qué no demuestra')])
  links=''.join(f'<a class="button" href="{escape(link["url"],quote=True)}">{escape(link["label"])}</a>' for link in decision['evidence'])
  cards+=f'<details class="dossier-decision" id="decision-{i}"><summary><span class="dossier-number">{i:02d}</span><span>{escape(decision["title"])}</span></summary><div class="dossier-body">{items}<div class="evidence-links" aria-label="Evidencia citada">{links}</div></div></details>'
 return '<section id="expediente" class="dossier"><p class="dossier-kicker">EXPEDIENTE · RETROSPECTIVA DE LABORATORIO</p><h2>De la observación a la decisión</h2><p>Abre una decisión para conectar su razonamiento con la sección concreta de la guía. Las alternativas son análisis editorial de este caso, no intentos adicionales ejecutados. No se recibió evidencia original independiente.</p>'+cards+'</section>'

def risk_exercise(bank,report):
 cards=''
 for r in bank['risks']:
  cards+=f'<article class="risk-option"><h3>{escape(r["finding"])} · {escape(r["title"])}</h3><p>{escape(r["scenario"])}</p><label>Orden de atención para {escape(r["finding"])}<select name="{escape(r["finding"])}" required><option value="">Elegir posición</option><option value="1">1 · Primero</option><option value="2">2 · Después</option><option value="3">3 · A continuación</option></select></label></article>'
 return f'''<section class="risk-exercise dossier" id="ejercicio"><p class="dossier-kicker">SIMULACIÓN LOCAL · NO ES UNA EVALUACIÓN PROFESIONAL</p><h2>¿Qué atenderías primero?</h2><p>Ordena tres condiciones ficticias. En este ejercicio suponemos que los pagos están activos, que puede suspenderse temporalmente el despliegue y que existe una copia externa de auditoría. Son supuestos didácticos adicionales, no hechos comprobados del informe.</p><form data-risk-form class="dossier-controls"><div class="risk-grid">{cards}</div><button class="button primary" type="submit">Comparar mi criterio</button></form><p class="dossier-fallback">El ejercicio es local y requiere JavaScript. La explicación completa está disponible debajo, también sin JavaScript.</p><div class="risk-feedback" data-risk-feedback role="status" aria-live="polite"></div><details class="dossier-decision"><summary><span>Leer el criterio y sus límites</span></summary><div class="dossier-body"><p><b>F02 primero:</b> el preparador puede aprobar su propio pago; con pagos activos, contener esa falta de independencia es urgente.</p><p><b>F07 después:</b> suspender despliegues y retirar la credencial reduce exposición mientras se corrigen privilegios y aprobaciones.</p><p><b>F10 a continuación:</b> proteger registros y verificar trazabilidad sigue siendo urgente; aquí suponemos una copia externa utilizable.</p><p>En el informe los tres son P0. Este orden pedagógico no modifica esa prioridad. Si hay despliegue no autorizado en curso o pérdida de trazabilidad, el orden puede cambiar; actuar en paralelo puede ser necesario. No hay puntuación ni certificación del visitante.</p><p>Los índices 20/25 y 15/25 pertenecen al modelo ficticio, no a CVSS ni a probabilidades anuales. <a href="{escape(report['sample_banca_html'],quote=True)}#bank_governance">Consultar apetito y tolerancias</a>.</p></div></details></section>'''

def demo_capture(task,root):
 import json
 path=root/'content/report-gen-demo-procedencia.json'
 if not path.is_file():return ''
 provenance=json.loads(path.read_text(encoding='utf-8'))
 captures={item['task']:item for item in provenance['images']}
 if task not in captures:return ''
 capture=captures[task]
 srcset=', '.join(escape(item['file'],quote=True)+' '+str(item['width'])+'w' for item in capture['variants'])
 return (f'<figure class="demo-capture"><picture><source type="image/webp" srcset="{srcset}" sizes="auto, (max-width:640px) calc(100vw - min(2.5rem, 16vw)), (max-width:900px) calc(100vw - 3rem), calc(900px - 4rem)">'
  f'<img src="{escape(capture["original"],quote=True)}" width="{capture["width"]}" height="{capture["height"]}" loading="lazy" decoding="async" alt="{escape(capture["alt"],quote=True)}"></picture>'
  f'<figcaption>{escape(capture["caption"])} <a href="{escape(capture["original"],quote=True)}" target="_blank" rel="noopener">Ampliar captura<span class="sr-only"> (abre otra pestaña)</span></a>.</figcaption></figure>')

def build_routes(document,page_head,record,report,root):
 journey='''<div class="shell narrow dossier-page"><p class="dossier-kicker">CUATRO PARADAS · LECTURA ESTIMADA DE 90 SEGUNDOS</p><p class="lead">Soy Sebastián, Pentester Junior en Santiago. Investigo seguridad web, Active Directory e IA/LLM, y construyo herramientas para documentar el trabajo con claridad. Este recorrido reúne mi criterio técnico, dos laboratorios y un resultado de reporting.</p><p id="journey-scope">Los tiempos son orientativos: puedes detenerte y abrir cada caso a tu ritmo. Con JavaScript, el raíl señala la sección que estás viendo; no mide tiempo ni registra lectura completada. Los cuatro enlaces funcionan también sin JavaScript.</p><div class="journey-layout"><nav class="journey-rail" data-journey-nav aria-label="Cuatro paradas del recorrido" aria-describedby="journey-scope"><ol><li><a href="#criterio"><span class="journey-dot" aria-hidden="true">01</span><span>Mi criterio</span></a></li><li><a href="#caso-web"><span class="journey-dot" aria-hidden="true">02</span><span>Seguridad web</span></a></li><li><a href="#caso-ad"><span class="journey-dot" aria-hidden="true">03</span><span>Active Directory</span></a></li><li><a href="#resultado"><span class="journey-dot" aria-hidden="true">04</span><span>Reporting</span></a></li></ol></nav><ol class="journey"><li id="criterio" data-journey-stop tabindex="-1" aria-labelledby="criterio-title"><p class="journey-time">Lectura estimada: 20 s</p><h2 id="criterio-title">Qué me importa</h2><p>Separar lo observado de lo supuesto. Un resultado tiene valor cuando puedo explicar su alcance, la evidencia y la decisión siguiente.</p><a class="button" href="fundamentos.html">Leer mi metodología</a></li><li id="caso-web" data-journey-stop tabindex="-1" aria-labelledby="caso-web-title"><p class="journey-time">Lectura estimada: 25 s</p><h2 id="caso-web-title">Una decisión en seguridad web</h2><p>Cap: comparar una captura propia con otra referencia permitió interpretar un fallo de autorización. Analizar el tráfico y revisar privilegios conecta los siguientes saltos, cada uno con evidencia documental propia.</p><a class="button" href="cap-caso.html#expediente">Abrir el expediente de Cap</a></li><li id="caso-ad" data-journey-stop tabindex="-1" aria-labelledby="caso-ad-title"><p class="journey-time">Lectura estimada: 25 s</p><h2 id="caso-ad-title">Una decisión en Active Directory</h2><p>Forest: una cuenta de servicio y relaciones de permisos explican la escalada. DCSync permite replicar material de autenticación; no demuestra pertenencia a Domain Admins.</p><a class="button" href="forest-caso.html#expediente">Abrir el expediente de Forest</a></li><li id="resultado" data-journey-stop tabindex="-1" aria-labelledby="resultado-title"><p class="journey-time">Lectura estimada: 20 s</p><h2 id="resultado-title">Cómo presento el resultado</h2><p>report-gen convierte hallazgos, evidencias y decisiones en entregas revisables. Banco Lumbre permite explorar su aplicación al riesgo empresarial con datos completamente ficticios.</p><div class="actions"><a class="button" href="report-gen-demo.html">Ver tres tareas de reporting</a><a class="button" href="banco-lumbre.html">Leer la simulación bancaria</a></div></li></ol></div><div class="notice">Cap y Forest son retrospectivas de laboratorios HTB. Banco Lumbre es una simulación ficticia. No presentan un encargo profesional ni un retest nuevo.</div><div class="actions"><a class="button primary" href="https://www.linkedin.com/in/sebastian-latorre-munoz/" target="_blank" rel="noopener">Contactar en LinkedIn</a><a class="button" href="guias.html">Explorar el laboratorio</a></div></div>'''
 document('recorrido.html','Recorrido breve','Un recorrido breve por mi criterio como pentester junior, casos documentados y una herramienta local de reporting.',page_head('Recorrido breve','Un primer vistazo al razonamiento detrás del laboratorio.',folder='readme',path='recorrido')+journey,'index',date_modified='2026-10-09')
 record('Recorrido breve','recorrido.html','Recorrido','Lectura estimada de 90 segundos, Pentester Junior, criterio, evidencia, Cap, Forest, report-gen','Portafolio')
 demo=f'''<div class="shell narrow dossier-page"><div class="notice"><b>Demostración didáctica.</b> Los paneles de texto representan tareas de report-gen {escape(report['version'])}; no son una aplicación remota. Las pantallas reales se identifican por su pie de captura y versión. Todos los datos de ejemplo son ficticios. La herramienta funciona localmente.</div><p>Elige una tarea. Puedes inspeccionar el objetivo, lo que revisaría y el resultado que entregaría sin descargar recursos adicionales.</p><nav class="demo-tabs" aria-label="Tareas de reporting"><a href="#demo-evidencia">1 · Documentar evidencia</a><a href="#demo-revision">2 · Revisar la entrega</a><a href="#demo-direccion">3 · Preparar la lectura ejecutiva</a></nav><section id="demo-evidencia" class="demo-task"><h2>1 · Documentar evidencia</h2><div class="demo-surface"><p class="demo-label">Ejemplo ficticio · F01</p><h3>Una cuenta consulta el documento de otra</h3><dl><dt>Qué demuestra</dt><dd>En el escenario sintético, la respuesta contiene un documento ajeno al cambiar su referencia.</dd><dt>Qué no demuestra</dt><dd>No acredita acceso a todos los documentos ni a una entidad real.</dd><dt>Contexto conservado</dt><dd>Activo, identidad, petición, respuesta y vínculo entre hallazgo y evidencia.</dd></dl></div><details class="dossier-decision"><summary><span>Qué revisaría antes de usar la captura</span></summary><div class="dossier-body"><p>Que la identidad y el objeto sean distintos, que la comparación tenga una referencia legítima y que la captura conserve suficiente contexto. Censuraría datos sensibles sobre la imagen, verificaría el resultado y conservaría el original privado cuando proceda.</p><p>Una imagen ilustrativa no se convierte en prueba ejecutada por añadirla al informe.</p></div></details></section><section id="demo-revision" class="demo-task"><h2>2 · Revisar la entrega</h2><div class="demo-surface"><p class="demo-label">Lista ilustrativa · no ejecutada desde esta página</p><ul><li>Referencias, metadatos y coherencia de las evidencias.</li><li>Texto, imágenes y destinos del índice del PDF.</li><li>Tablas, títulos, capturas y paginación mediante revisión visual.</li><li>Avisos pendientes reconocidos y preservados en la entrega.</li></ul></div><details class="dossier-decision"><summary><span>Qué significa una comprobación correcta</span></summary><div class="dossier-body"><p>Comprueba propiedades del archivo producido; no vuelve a ejecutar un pentest ni verifica que una vulnerabilidad esté corregida. Los avisos necesitan una decisión del autor. Revisaría PDF y Word en el entorno del destinatario.</p></div></details></section><section id="demo-direccion" class="demo-task"><h2>3 · Preparar la lectura ejecutiva</h2><div class="demo-surface"><p class="demo-label">Banco Lumbre · SIMULACIÓN</p><h3>Pagos sin aprobación independiente</h3><p><b>Consecuencia del guion:</b> una misma identidad prepara y aprueba un pago.</p><p><b>Decisión propuesta:</b> separar funciones y validar la autorización en el servidor.</p><p><b>Verificación pendiente:</b> probar casos positivos y negativos tras implementar el control. No hubo un pago real ni retest.</p></div><details class="dossier-decision"><summary><span>Cómo adaptar el contenido al destinatario</span></summary><div class="dossier-body"><p>Dirección necesita alcance, consecuencia, prioridades, límites y decisiones. El equipo técnico necesita reproducción, evidencias y remediación. Los perfiles generan archivos independientes con contenido seleccionado y exclusiones reales. Para un extracto público, redactaría texto nuevo, usaría un alias y registraría los permisos de publicación. Revisaría siempre el plan y el archivo producido. Cambiar la vista o aplicar un filtro al HTML completo solo altera su presentación; no elimina datos de ese archivo.</p></div></details><a class="button" href="banco-lumbre.html#ejercicio">Practicar una decisión de riesgo ficticia</a></section><div class="actions"><a class="button primary" href="{escape(report['download'],quote=True)}" download>Descargar report-gen {escape(report['version'])}</a><a class="button" href="{escape(report['guide'],quote=True)}">Guía de uso</a><a class="button" href="proyectos.html#report-gen">Ver el proyecto completo</a></div></div>'''
 demo=demo.replace('<nav class="demo-tabs"', '<p>En la app local, abre «Evidencia y decisiones» desde la barra lateral. En móvil, está dentro de «Más». Sus pestañas corresponden a estas tareas.</p><nav class="demo-tabs"',1)
 instructions={
  'demo-evidencia':'<ol class="demo-steps"><li>Abre «Afirmaciones y evidencia» y selecciona el hallazgo.</li><li>Elige el tipo de afirmación, redacta qué demuestra y qué no demuestra, y vincula la evidencia concreta.</li><li>Pulsa «Guardar afirmación» y revisa su contexto y límites.</li></ol>',
  'demo-revision':'<ol class="demo-steps"><li>Abre «Mesa de revisión» y selecciona contexto y campo.</li><li>Escribe la observación y su autor local; pulsa «Guardar observación».</li><li>Revisa el contenido y registra la revisión editorial. Resolver una observación no demuestra una remediación verificada.</li></ol>',
  'demo-direccion':'<ol class="demo-steps"><li>Abre «Entregas por destinatario» y elige el perfil y los hallazgos.</li><li>Pulsa «Comprobar qué se incluirá» y revisa inclusiones, exclusiones y contenido real del plan.</li><li>Selecciona formatos, reconoce los avisos que correspondan y usa «Generar y descargar ZIP». Revisa los archivos antes de compartirlos.</li></ol>'
 }
 for section,instruction in instructions.items():
  section_start=demo.index(f'<section id="{section}" class="demo-task">')
  heading_end=demo.index('</h2>',section_start)+5
  demo=demo[:heading_end]+instruction+demo[heading_end:]
 for task,section in [('evidence','demo-evidencia'),('review','demo-revision'),('executive','demo-direccion')]:
  caption=demo_capture(task,root)
  if caption:
   marker=f'<section id="{section}" class="demo-task">'
   section_start=demo.index(marker)
   heading_end=demo.index('</h2>',section_start)+5
   demo=demo[:heading_end]+caption+demo[heading_end:]
 document('report-gen-demo.html','Tres tareas con report-gen','Demostración didáctica del reporting local: evidencia, revisión de la entrega y comunicación ejecutiva con datos ficticios.',page_head('Tres tareas con report-gen','Del hallazgo a una entrega que puedes explicar y revisar.',folder='proyectos',path='report-gen/demo')+demo,'proyectos',date_modified='2026-10-10')
 record('Tres tareas con report-gen','report-gen-demo.html','Demo','Documentar evidencia, revisar entregas, lectura ejecutiva, datos ficticios','Reporting')
 notebook='''<div class="shell narrow dossier-page"><p class="lead">Guarda guías, técnicas y casos, anota lo que quieres repasar y retoma una lectura. Los datos permanecen en este navegador; no se envían a un servidor ni se sincronizan entre dispositivos.</p><div class="notice">Las notas son personales: evita introducir credenciales o información de clientes. La exportación incluye tus notas. Borrar elimina el cuaderno de este navegador, no archivos exportados.</div><div class="notebook-controls"><button class="button notebook-control" type="button" data-notebook-export="json">Exportar mi cuaderno (JSON)</button><button class="button notebook-control" type="button" data-notebook-export="links">Exportar enlaces (TXT)</button><button class="button notebook-control" type="button" data-notebook-import aria-controls="cuaderno-importacion" aria-expanded="false">Importar cuaderno (JSON)</button><button class="button notebook-control" type="button" data-notebook-clear aria-expanded="false" aria-controls="cuaderno-borrado">Revisar borrado del cuaderno</button></div><section id="cuaderno-importacion" data-notebook-import-panel hidden aria-labelledby="cuaderno-import-title"><h2 id="cuaderno-import-title">Añadir desde un respaldo</h2><p>JSON de este cuaderno, versión 1, máximo 4 MiB, 200 favoritos y 40 puntos de lectura. Se añade contenido; tus favoritos, notas y puntos existentes se conservan ante coincidencias. No hay sincronización.</p><label for="cuaderno-import-file">Elegir archivo JSON</label><input id="cuaderno-import-file" data-notebook-import-file type="file" accept=".json,application/json"><p data-notebook-import-preview role="status" aria-live="polite">Selecciona un archivo para revisarlo antes de añadirlo.</p><div class="actions"><button type="button" class="button" data-notebook-import-apply disabled>Añadir contenido revisado</button><button type="button" class="button" data-notebook-import-cancel>Cancelar importación</button></div></section><div id="cuaderno-borrado" data-notebook-clear-confirm hidden><p>¿Eliminar favoritos, notas y puntos de lectura de este navegador?</p><button class="button" type="button" data-notebook-clear-cancel>Conservar mi cuaderno</button><button class="button" type="button" data-notebook-clear-yes>Eliminar mi cuaderno</button></div><p data-notebook-status role="status" aria-live="polite"></p><section aria-labelledby="saved-title"><h2 id="saved-title">Mis favoritos</h2><div data-notebook-list><p>El cuaderno requiere JavaScript. Puedes explorar todas las <a href="guias.html">guías</a> y <a href="tecnicas.html">técnicas</a> sin activarlo.</p></div></section><section aria-labelledby="resume-title"><h2 id="resume-title">Continuar leyendo</h2><div data-notebook-resume><p>Los puntos de lectura aparecerán aquí al recorrer un artículo con JavaScript activo.</p></div></section></div>'''
 document('cuaderno.html','Mi cuaderno de laboratorio','Favoritos, notas y puntos de lectura guardados únicamente en tu navegador, con exportación y borrado explícito.',page_head('Mi cuaderno de laboratorio','Un espacio personal para volver a lo que quieres estudiar.',folder='readme',path='cuaderno')+notebook,'guias',date_modified='2026-10-08')
